    Bug 1999822 - Write correct UTF-8 for search term values. r=mkmelin


    nsIMsgSearchTerm.termAsString is used in MsgTermListToString() to write the search term values to a string that is later written to a file.

    Differential Revision: https://phabricator.services.mozilla.com/D272343

diff --git a/mailnews/base/src/nsMsgAccountManager.cpp b/mailnews/base/src/nsMsgAccountManager.cpp
index 3420835a3d8..218a5d62e90 100644
--- a/mailnews/base/src/nsMsgAccountManager.cpp
+++ b/mailnews/base/src/nsMsgAccountManager.cpp
@@ -2420,7 +2420,7 @@ nsresult VirtualFolderChangeListener::Init() {
     nsCOMPtr<nsIMsgFilter> tempFilter;
     filterList->CreateFilter(u"temp"_ns, getter_AddRefs(tempFilter));
     NS_ENSURE_SUCCESS(rv, rv);
-    filterList->ParseCondition(tempFilter, searchTermString.get());
+    filterList->ParseCondition(tempFilter, searchTermString);
     NS_ENSURE_SUCCESS(rv, rv);
     m_searchSession =
         do_CreateInstance("@mozilla.org/messenger/searchSession;1", &rv);
diff --git a/mailnews/db/panorama/src/VirtualFolderWrapper.cpp b/mailnews/db/panorama/src/VirtualFolderWrapper.cpp
index bc002921ef7..19bb9f23381 100644
--- a/mailnews/db/panorama/src/VirtualFolderWrapper.cpp
+++ b/mailnews/db/panorama/src/VirtualFolderWrapper.cpp
@@ -103,7 +103,7 @@ NS_IMETHODIMP VirtualFolderWrapper::GetSearchTermsSession(
   nsAutoCString searchString;
   GetSearchString(searchString);
   filterList->CreateFilter(u"temp"_ns, filter);
-  filterList->ParseCondition(*filter, searchString.get());
+  filterList->ParseCondition(*filter, searchString);
   return NS_OK;
 }

